// ── RECIPE VIEW ────────────────────────────────────────────────────────
function RecipeView({ country, dish, onBack, navigate }) {
  const [recipe, setRecipe] = useState(null);
  const [loading, setLoading] = useState(true);
  const flag = COUNTRY_DISHES[country]?.flag || "🌍";

  useEffect(() => {
    setLoading(false);
    if (RECIPE_DB[dish]) { setRecipe(RECIPE_DB[dish]); }
    else { setRecipe({ error: true }); }
  }, [dish, country]);

  return (
    <div style={{ maxWidth:700, margin:"0 auto" }}>
      <button className="btn-ghost" onClick={onBack} style={{ marginBottom:24 }}>← Back to {country || recipeCountry}</button>
      <AdUnit />
      <div style={{ marginTop:24 }}>
        {loading ? (
          <div style={{ textAlign:"center", padding:"60px 0" }}>
            <div className="spinner" style={{ width:24, height:24, margin:"0 auto 14px" }} />
            <p style={{ fontSize:14, color:"#b8b0a8", fontStyle:"italic" }}>Preparing your recipe…</p>
          </div>
        ) : recipe && !recipe.error ? (
          <div>
            <div style={{ marginBottom:28 }}>
              {country && <div style={{ display:"inline-block", background:"#fdf3ed", borderRadius:100, padding:"4px 12px", fontSize:11, color:"#c2622a", fontWeight:600, letterSpacing:".06em", textTransform:"uppercase", marginBottom:12 }}>
                {country}
              </div>}
              <h1 style={{ fontFamily:"Fraunces", fontSize:32, fontWeight:700, color:"#1a1714", marginBottom:10, lineHeight:1.2 }}>{recipe.name}</h1>
              {recipe.story && <p style={{ fontSize:13, color:"#b8b0a8", fontStyle:"italic", marginBottom:10, lineHeight:1.7 }}>{recipe.story}</p>}
              <p style={{ fontSize:15, color:"#6a6058", lineHeight:1.85, marginBottom:16 }}>{recipe.description}</p>
              {recipe.image && (
                <div style={{ marginBottom:6, borderRadius:12, overflow:"hidden", boxShadow:"0 2px 12px rgba(0,0,0,.08)", background:"#f0e8e0" }}>
                  <img src={recipe.image} alt={`Authentic ${recipe.country} ${recipe.name} recipe`}
                    style={{ width:"100%", height:260, objectFit:"cover", display:"block" }}
                  />
                </div>
              )}
              {recipe.photoCredit && (
                <div style={{ textAlign:"right", marginBottom:14 }}>
                  <a href={recipe.photoCredit.url} target="_blank" rel="noopener noreferrer"
                    style={{ fontSize:10, color:"#c8bfb0", fontFamily:"Plus Jakarta Sans", textDecoration:"none" }}>
                    Photo: {recipe.photoCredit.name}
                  </a>
                </div>
              )}
              <div className="stat-row" style={{ display:"flex", gap:10, flexWrap:"wrap" }}>
                {[{l:"Prep",v:recipe.prepTime},{l:"Cook",v:recipe.cookTime},{l:"Serves",v:recipe.serves},{l:"Difficulty",v:recipe.difficulty}].map(({l,v})=>(
                  <div key={l} style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:10, padding:"8px 16px", textAlign:"center", minWidth:80, boxShadow:"0 1px 3px rgba(0,0,0,.04)" }}>
                    <div style={{ fontSize:10, color:"#b8b0a8", letterSpacing:".07em", textTransform:"uppercase", marginBottom:3, fontWeight:600 }}>{l}</div>
                    <div style={{ fontSize:13, fontWeight:600, color:"#1a1714" }}>{v}</div>
                  </div>
                ))}
              </div>
            </div>
            <div style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:14, padding:24, marginBottom:12, boxShadow:"0 1px 4px rgba(0,0,0,.04)" }}>
              <h3 style={{ fontFamily:"Fraunces", fontSize:19, marginBottom:18, color:"#1a1714" }}>Ingredients</h3>
              <div className="ing-grid" style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:"0 20px" }}>
                {(recipe.ingredients||[]).map((ing,i)=>(
                  <div key={i} style={{ display:"flex", gap:10, paddingBottom:9, borderBottom:"1px solid #f5f0e8", marginBottom:1, alignItems:"baseline" }}>
                    <span style={{ fontSize:12, fontWeight:700, color:ACCENT, minWidth:60, flexShrink:0 }}>{ing.amount}</span>
                    <span style={{ fontSize:13, color:"#5a5048" }}>{ing.item}</span>
                  </div>
                ))}
              </div>
            </div>
            <div style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:14, padding:24, marginBottom:12, boxShadow:"0 1px 4px rgba(0,0,0,.04)" }}>
              <h3 style={{ fontFamily:"Fraunces", fontSize:19, marginBottom:20, color:"#1a1714" }}>Method</h3>
              <div style={{ display:"flex", flexDirection:"column", gap:16 }}>
                {(recipe.steps||[]).map((step,i)=>(
                  <div key={i} style={{ display:"flex", gap:14, alignItems:"flex-start" }}>
                    <div className="step-num">{i+1}</div>
                    <p style={{ fontSize:14, color:"#5a5048", lineHeight:1.8, paddingTop:3 }}>{step}</p>
                  </div>
                ))}
              </div>
            </div>
            {recipe.tip && (
              <div style={{ background:"#fdf8f3", border:"1.5px solid #f0e4d4", borderRadius:14, padding:18, borderLeft:`4px solid ${ACCENT}`, marginBottom:12 }}>
                <div style={{ fontSize:11, color:ACCENT, letterSpacing:".08em", textTransform:"uppercase", fontWeight:700, marginBottom:6 }}>Chef's Tip</div>
                <p style={{ fontSize:14, color:"#6a6058", lineHeight:1.75 }}>{recipe.tip}</p>
              </div>
            )}
            <div style={{ marginTop:20 }}><AdUnit /></div>

            {/* You may also like */}
            {(() => {
              const currentCountry = recipe.country;
              const region = REGIONS.find(r => r.countries?.includes(currentCountry));
              // Same country first, excluding current recipe
              const sameCountry = Object.keys(RECIPE_DB)
                .filter(k => RECIPE_DB[k].country === currentCountry && RECIPE_DB[k].name !== recipe.name);
              // Fill from same region if needed
              const sameRegion = region
                ? Object.keys(RECIPE_DB).filter(k =>
                    region.countries?.includes(RECIPE_DB[k].country) &&
                    RECIPE_DB[k].country !== currentCountry &&
                    RECIPE_DB[k].name !== recipe.name)
                : [];
              const pool = [...sameCountry, ...sameRegion];
              const shuffled = [...pool].sort(() => Math.random() - 0.5).slice(0, 3);
              if (shuffled.length === 0) return null;
              return (
                <div style={{ marginTop:32 }}>
                  <div style={{ marginBottom:16 }}>
                    <h2 style={{ fontFamily:"Fraunces", fontSize:"clamp(18px,2.5vw,24px)", fontWeight:700, color:"#1a1714", margin:0 }}>You may also like</h2>
                    <p style={{ fontSize:13, color:"#9a9088", margin:"4px 0 0" }}>More recipes you might enjoy</p>
                  </div>
                  <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit, minmax(220px, 1fr))", gap:16 }}>
                    {shuffled.map((key, i) => {
                      const rec = RECIPE_DB[key];
                      const reg = REGIONS.find(r => r.countries?.includes(rec.country));
                      return (
                        <div key={i}
                          onClick={() => navigate(`/${reg?.id || ""}/${slugify(rec.country)}/${slugify(rec.name)}`)}
                          style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:12, overflow:"hidden", cursor:"pointer", transition:"transform .15s, box-shadow .15s" }}
                          onMouseEnter={e => { e.currentTarget.style.transform="translateY(-2px)"; e.currentTarget.style.boxShadow="0 6px 20px rgba(0,0,0,.08)"; }}
                          onMouseLeave={e => { e.currentTarget.style.transform="none"; e.currentTarget.style.boxShadow="none"; }}>
                          <div style={{ width:"100%", height:160, overflow:"hidden", background:"#f0e8e0" }}>
                            <img src={rec.image} alt={`Authentic ${rec.country} ${rec.name} recipe`} style={{ width:"100%", height:"100%", objectFit:"cover", display:"block" }} />
                          </div>
                          <div style={{ padding:"12px 14px 14px" }}>
                            <div style={{ display:"flex", alignItems:"center", gap:6, marginBottom:6 }}>
                              <span style={{ fontSize:14 }}>{COUNTRY_DISHES[rec.country]?.flag}</span>
                              <span style={{ fontSize:11, color:"#9a9088", fontFamily:"Plus Jakarta Sans", fontWeight:500 }}>{rec.country}</span>
                            </div>
                            <div style={{ fontFamily:"Fraunces", fontSize:16, fontWeight:700, color:"#1a1714", lineHeight:1.3, marginBottom:4 }}>{rec.name}</div>
                            <div style={{ fontSize:12, color:"#c2622a", fontWeight:600, fontFamily:"Plus Jakarta Sans" }}>View recipe →</div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })()}

            {/* Third ad unit */}
            <div style={{ marginTop:24 }}><AdUnit /></div>
          </div>
        ) : (
          <div style={{ textAlign:"center", padding:"40px 0", color:"#b8b0a8" }}>Couldn't load this recipe — please try again.</div>
        )}
      </div>
    </div>
  );
}

// ── MAIN APP ───────────────────────────────────────────────────────────
function slugify(s) {
  if (!s || typeof s !== 'string') return '';
  const map = {'à':'a','á':'a','â':'a','ã':'a','ä':'a','å':'a','è':'e','é':'e','ê':'e','ë':'e','ì':'i','í':'i','î':'i','ï':'i','ò':'o','ó':'o','ô':'o','õ':'o','ö':'o','ù':'u','ú':'u','û':'u','ü':'u','ý':'y','ÿ':'y','ñ':'n','ç':'c','ß':'ss','ž':'z','ż':'z','ź':'z','ł':'l','š':'s','ă':'a','ț':'t','ő':'o','ű':'u','ā':'a','ē':'e','ī':'i','ō':'o','ū':'u'};
  return s.toLowerCase().split('').map(c => map[c] || c).join('').replace(/[^a-z0-9\s-]/g,'').replace(/[\s_]+/g,'-').trim();
}

function unslugify(slug, lookup) {
  if (!slug || !lookup) return null;
  return Object.keys(lookup).find(k =>
    slugify(k) === slug ||
    (lookup[k] && lookup[k].name && slugify(lookup[k].name) === slug)
  ) || null;
}

// ── ROUTER ────────────────────────────────────────────────────────────
function App() {
  const [path, setPath] = useState(() => window.location.pathname);

  useEffect(() => {
    const handler = () => setPath(window.location.pathname);
    window.addEventListener('popstate', handler);
    return () => window.removeEventListener('popstate', handler);
  }, []);

  const navigate = (to) => {
    if (to === -1) { window.history.back(); return; }
    window.history.pushState({}, '', to);
    window.scrollTo(0, 0);
    document.documentElement.scrollTo(0, 0);
    document.body.scrollTo(0, 0);
    setPath(to);
  };

  // Derive view from hierarchical URL: /europe, /europe/italy, /europe/italy/tiramisu
  const safePath = typeof path === 'string' ? path : '/';
  const parts = safePath.split('/').filter(Boolean);
  const infoPages = ['blog','about','contact','privacy','terms'];

  let view = 'regions';
  let selectedRegion = null;
  let selectedCountry = null;
  let selectedDish = null;

  if (parts.length === 0) {
    view = 'regions';
  } else if (infoPages.includes(parts[0])) {
    view = parts[0];
  } else if (parts.length === 1) {
    const region = REGIONS.find(r => r.id === parts[0]);
    if (region) { view = 'region'; selectedRegion = parts[0]; }
  } else if (parts.length === 2) {
    const region = REGIONS.find(r => r.id === parts[0]);
    const country = unslugify(parts[1], COUNTRY_DISHES);
    if (region && country) { view = 'country'; selectedRegion = parts[0]; selectedCountry = country; }
  } else if (parts.length === 3) {
    const region = REGIONS.find(r => r.id === parts[0]);
    const country = unslugify(parts[1], COUNTRY_DISHES);
    const dish = unslugify(parts[2], RECIPE_DB);
    if (region && country && dish) { view = 'recipe'; selectedRegion = parts[0]; selectedCountry = country; selectedDish = dish; }
  }

  const recipeCountry = selectedDish ? RECIPE_DB[selectedDish]?.country : null;
  const countryRegion = selectedCountry ? REGIONS.find(r => r.countries?.includes(selectedCountry)) : null;

  // ── DYNAMIC TITLE & META DESCRIPTION ──────────────────────────────────
  useEffect(() => {
    let title = 'Recipe Atlas — World Cuisine Explorer';
    let description = 'Explore authentic recipes from 44 countries and 7 regions. From Italian carbonara to Georgian khachapuri — discover the world through food.';

    if (view === 'recipe' && selectedDish) {
      const recipe = RECIPE_DB[selectedDish];
      const country = recipeCountry || recipe?.country || '';
      title = `${selectedDish} — Authentic ${country} Recipe | Recipe Atlas`;
      description = recipe?.description
        ? `${recipe.description.replace(/\.+$/, '')}.`
        : `Learn how to make ${selectedDish}, an authentic ${country} dish. Full recipe with ingredients, steps and cultural background.`;
    } else if (view === 'country' && selectedCountry) {
      const flag = COUNTRY_DISHES[selectedCountry]?.flag || '';
      const dishes = COUNTRY_DISHES[selectedCountry]?.dishes?.slice(0, 3).join(', ') || '';
      title = `${selectedCountry} Recipes — Authentic ${selectedCountry} Dishes & Cuisine | Recipe Atlas`;
      description = `Explore authentic ${selectedCountry} recipes including ${dishes} and more. Discover the flavours, techniques and stories behind ${selectedCountry}'s greatest dishes.`;
    } else if (view === 'region' && selectedRegion) {
      const region = REGIONS.find(r => r.id === selectedRegion);
      const regionName = region?.name || selectedRegion;
      const countries = region?.countries?.slice(0, 4).join(', ') || '';
      title = `${regionName} Recipes — Authentic Dishes from ${countries} & More | Recipe Atlas`;
      description = `${region?.description || `Explore the best recipes from ${regionName}`}. Browse authentic dishes from every country in the region.`;
    } else if (view === 'blog') {
      title = 'The Recipe Atlas Blog — Food Stories, Techniques & History';
      description = 'In-depth articles on cooking science, world food history, ingredients and techniques. Stories from the world\'s great food cultures.';
    } else if (view === 'about') {
      title = 'About Recipe Atlas — World Cuisine Explorer';
      description = 'Recipe Atlas celebrates the extraordinary diversity of world cuisine across 44 countries and 7 regions. Learn about our mission and approach.';
    } else if (view === 'contact') {
      title = 'Contact Recipe Atlas — Get in Touch';
      description = 'Get in touch with Recipe Atlas for general enquiries, advertising opportunities, recipe submissions or partnerships. We\'d love to hear from you.';
    } else if (view === 'privacy') {
      title = 'Privacy Policy | Recipe Atlas';
      description = 'Read the Recipe Atlas privacy policy covering data collection, cookies, analytics and advertising.';
    }

    // Ensure title ends cleanly and description ends with full stop
    if (description && !description.endsWith('.')) description += '.';

    document.title = title;

    // Canonical URL
    const canonicalHref = 'https://recipeatlas.co.uk' + window.location.pathname;
    let canonicalTag = document.querySelector('link[rel="canonical"]');
    if (!canonicalTag) {
      canonicalTag = document.createElement('link');
      canonicalTag.rel = 'canonical';
      document.head.appendChild(canonicalTag);
    }
    canonicalTag.href = canonicalHref;

    let metaDesc = document.querySelector('meta[name="description"]');
    if (!metaDesc) {
      metaDesc = document.createElement('meta');
      metaDesc.name = 'description';
      document.head.appendChild(metaDesc);
    }
    metaDesc.content = description;

    // Open Graph tags for social sharing
    const setOG = (property, content) => {
      let tag = document.querySelector(`meta[property="${property}"]`);
      if (!tag) { tag = document.createElement('meta'); tag.setAttribute('property', property); document.head.appendChild(tag); }
      tag.content = content;
    };
    setOG('og:title', title);
    setOG('og:description', description);
    setOG('og:type', 'website');
    setOG('og:url', window.location.href);
    if (view === 'recipe' && selectedDish && RECIPE_DB[selectedDish]?.image) {
      setOG('og:image', RECIPE_DB[selectedDish].image);
    }

    // ── RECIPE JSON-LD STRUCTURED DATA ──────────────────────────────────
    let jsonLd = document.querySelector('script[data-schema="recipe"]');
    if (view === 'recipe' && selectedDish && RECIPE_DB[selectedDish]) {
      const r = RECIPE_DB[selectedDish];
      const schemaData = {
        "@context": "https://schema.org",
        "@type": "Recipe",
        "name": r.name,
        "image": [r.image],
        "description": r.description || '',
        "keywords": `${r.name}, ${r.country} recipe, authentic ${r.country} food, ${r.name.toLowerCase()} recipe`,
        "recipeCategory": "Main Course",
        "recipeCuisine": r.country,
        "prepTime": r.prepTime ? "PT" + r.prepTime.replace(/\s*mins?/i, 'M').replace(/\s*hours?/i, 'H') : undefined,
        "cookTime": r.cookTime ? "PT" + r.cookTime.replace(/\s*mins?/i, 'M').replace(/\s*hours?/i, 'H') : undefined,
        "recipeYield": r.serves ? `${r.serves} servings` : undefined,
        "recipeIngredient": r.ingredients ? r.ingredients.map(ing => `${ing.amount} ${ing.item}`) : [],
        "recipeInstructions": r.steps ? r.steps.map((step, i) => ({
          "@type": "HowToStep",
          "position": i + 1,
          "text": step
        })) : [],
        "author": { "@type": "Organization", "name": "Recipe Atlas" },
        "publisher": { "@type": "Organization", "name": "Recipe Atlas", "url": "https://recipeatlas.co.uk" },
        "url": "https://recipeatlas.co.uk" + window.location.pathname,
      };
      // Remove undefined fields
      Object.keys(schemaData).forEach(k => schemaData[k] === undefined && delete schemaData[k]);
      if (!jsonLd) {
        jsonLd = document.createElement('script');
        jsonLd.type = 'application/ld+json';
        jsonLd.setAttribute('data-schema', 'recipe');
        document.head.appendChild(jsonLd);
      }
      jsonLd.textContent = JSON.stringify(schemaData);
    } else {
      // Remove schema when not on a recipe page
      if (jsonLd) jsonLd.remove();
    }

    // ── BREADCRUMB JSON-LD ───────────────────────────────────────────────
    let breadcrumbLd = document.querySelector('script[data-schema="breadcrumb"]');
    const breadcrumbs = [{ name: 'Home', url: 'https://recipeatlas.co.uk/' }];
    if (view === 'region' && selectedRegion) {
      const region = REGIONS.find(r => r.id === selectedRegion);
      if (region) breadcrumbs.push({ name: region.name + ' Recipes', url: 'https://recipeatlas.co.uk/' + selectedRegion });
    } else if (view === 'country' && selectedCountry) {
      const region = REGIONS.find(r => r.countries?.includes(selectedCountry));
      if (region) breadcrumbs.push({ name: region.name + ' Recipes', url: 'https://recipeatlas.co.uk/' + region.id });
      breadcrumbs.push({ name: selectedCountry + ' Recipes', url: 'https://recipeatlas.co.uk/' + (region?.id || '') + '/' + selectedCountry.toLowerCase().replace(/\s+/g, '-') });
    } else if (view === 'recipe' && selectedDish) {
      const recipe = RECIPE_DB[selectedDish];
      const country = recipeCountry || recipe?.country || '';
      const region = REGIONS.find(r => r.countries?.includes(country));
      if (region) breadcrumbs.push({ name: region.name + ' Recipes', url: 'https://recipeatlas.co.uk/' + region.id });
      breadcrumbs.push({ name: country + ' Recipes', url: 'https://recipeatlas.co.uk/' + (region?.id || '') + '/' + country.toLowerCase().replace(/\s+/g, '-') });
      breadcrumbs.push({ name: selectedDish, url: 'https://recipeatlas.co.uk' + window.location.pathname });
    }
    if (breadcrumbs.length > 1) {
      const breadcrumbSchema = {
        '@context': 'https://schema.org',
        '@type': 'BreadcrumbList',
        'itemListElement': breadcrumbs.map((crumb, i) => ({
          '@type': 'ListItem',
          'position': i + 1,
          'name': crumb.name,
          'item': crumb.url
        }))
      };
      if (!breadcrumbLd) {
        breadcrumbLd = document.createElement('script');
        breadcrumbLd.type = 'application/ld+json';
        breadcrumbLd.setAttribute('data-schema', 'breadcrumb');
        document.head.appendChild(breadcrumbLd);
      }
      breadcrumbLd.textContent = JSON.stringify(breadcrumbSchema);
    } else {
      if (breadcrumbLd) breadcrumbLd.remove();
    }

    // ── WEBSITE + ORGANIZATION SCHEMAS (injected once) ───────────────────
    if (!document.querySelector('script[data-schema="website"]')) {
      const websiteSchema = {
        '@context': 'https://schema.org',
        '@type': 'WebSite',
        'name': 'Recipe Atlas',
        'url': 'https://recipeatlas.co.uk',
        'description': 'Explore authentic recipes from 44 countries and 7 regions. Discover the world through food.',
        'potentialAction': {
          '@type': 'SearchAction',
          'target': { '@type': 'EntryPoint', 'urlTemplate': 'https://recipeatlas.co.uk/?q={search_term_string}' },
          'query-input': 'required name=search_term_string'
        }
      };
      const wsTag = document.createElement('script');
      wsTag.type = 'application/ld+json';
      wsTag.setAttribute('data-schema', 'website');
      wsTag.textContent = JSON.stringify(websiteSchema);
      document.head.appendChild(wsTag);
    }
    if (!document.querySelector('script[data-schema="organization"]')) {
      const orgSchema = {
        '@context': 'https://schema.org',
        '@type': 'Organization',
        'name': 'Recipe Atlas',
        'url': 'https://recipeatlas.co.uk',
        'logo': 'https://recipeatlas.co.uk/favicon.svg',
        'contactPoint': { '@type': 'ContactPoint', 'email': 'contact.jwgroup@proton.me', 'contactType': 'customer support' }
      };
      const orgTag = document.createElement('script');
      orgTag.type = 'application/ld+json';
      orgTag.setAttribute('data-schema', 'organization');
      orgTag.textContent = JSON.stringify(orgSchema);
      document.head.appendChild(orgTag);
    }

  }, [view, selectedDish, selectedCountry, selectedRegion]);
  // ── END DYNAMIC META ───────────────────────────────────────────────────

  const goToRegion      = (rid) => navigate(`/${rid}`);
  const goToCountry     = (c)   => { const r = REGIONS.find(r => r.countries?.includes(c)); navigate(`/${r ? r.id : ""}/${slugify(c)}`); };
  const goToDish        = (d)   => {
    // d may be a display name like "Pan-Fried Barramundi" or a DB key like "Barramundi"
    // Find the actual DB key by checking both direct match and name match
    const key = RECIPE_DB[d] ? d : Object.keys(RECIPE_DB).find(k => RECIPE_DB[k].name === d || slugify(RECIPE_DB[k].name) === slugify(d)) || d;
    if (!RECIPE_DB[key]) return; // recipe not yet available
    const country = RECIPE_DB[key]?.country;
    const r = REGIONS.find(r => r.countries?.includes(country));
    navigate(`/${r ? r.id : ""}/${slugify(country || "")}/${slugify(RECIPE_DB[key]?.name || key)}`);
  };
  const goToRegions     = ()    => navigate('/');
  const goToRegionBack  = ()    => navigate(selectedRegion ? `/${selectedRegion}` : '/');
  const goToCountryBack = ()    => navigate(selectedRegion && selectedCountry ? `/${selectedRegion}/${slugify(selectedCountry)}` : selectedRegion ? `/${selectedRegion}` : '/');

  const region = REGIONS.find(r => r.id === selectedRegion);

  return (
    <>
      <style>{styles}</style>
      <div style={{ minHeight:"100vh", background:"#fdfcf9" }}>
        {/* Header */}
        <div style={{ background:"#fff", borderBottom:"1.5px solid #ece6db", padding:"13px 28px", display:"flex", alignItems:"center", justifyContent:"space-between", flexWrap:"wrap", gap:12, position:"sticky", top:0, zIndex:50, boxShadow:"0 1px 8px rgba(0,0,0,.05)" }}>
          <div style={{ cursor:"pointer", display:"flex", alignItems:"center", gap:12 }} onClick={goToRegions}>
            <div style={{ width:36, height:36, background:"linear-gradient(135deg,#c2622a,#e8832a)", borderRadius:10, display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0, boxShadow:"0 2px 8px rgba(194,98,42,.35)" }}>
              <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                <circle cx="14" cy="12" r="8" stroke="#fff" strokeWidth="1.8" fill="none"/>
                <path d="M6 12 Q14 8 22 12" stroke="#fff" strokeWidth="1.4" fill="none"/>
                <path d="M6 12 Q14 16 22 12" stroke="#fff" strokeWidth="1.4" fill="none"/>
                <line x1="14" y1="4" x2="14" y2="20" stroke="#fff" strokeWidth="1.4"/>
                <line x1="3" y1="4" x2="3" y2="20" stroke="#fff" strokeWidth="2" strokeLinecap="round"/>
                <line x1="1" y1="4" x2="1" y2="9" stroke="#fff" strokeWidth="1.6" strokeLinecap="round"/>
                <line x1="5" y1="4" x2="5" y2="9" stroke="#fff" strokeWidth="1.6" strokeLinecap="round"/>
                <path d="M1 9 Q3 13 5 9" stroke="#fff" strokeWidth="1.6" fill="none"/>
              </svg>
            </div>
            <div>
              <div style={{ fontFamily:"Fraunces", fontSize:18, fontWeight:700, color:"#1a1714" }}>Recipe Atlas</div>
              <div style={{ fontSize:10, color:"#b8b0a8", letterSpacing:".1em", textTransform:"uppercase", fontWeight:500 }}>World Cuisine Explorer</div>
            </div>
          </div>
          {view !== "regions" && (
            <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:12, color:"#b8b0a8", flexWrap:"wrap" }}>
              {view === "recipe" && recipeCountry ? (
                <>
                  <span style={{ cursor:"pointer", color:"#9a9088", fontWeight:500 }} onClick={() => { const r = REGIONS.find(r => r.countries?.includes(recipeCountry)); navigate(`/${r ? r.id : ""}/${slugify(recipeCountry)}`); }}>{recipeCountry}</span>
                  {selectedDish && <><span>›</span><span style={{ color:"#1a1714", fontWeight:600 }}>{selectedDish}</span></>}
                </>
              ) : (
                <>
                  <span style={{ cursor:"pointer", color:"#9a9088", fontWeight:500 }} onClick={goToRegions}>Regions</span>
                  {selectedRegion && <><span>›</span><span style={{ cursor:"pointer", color: view!=="region"?"#9a9088":"#1a1714", fontWeight:500 }} onClick={goToRegionBack}>{region?.name}</span></>}
                  {!selectedRegion && countryRegion && <><span>›</span><span style={{ cursor:"pointer", color:"#9a9088", fontWeight:500 }} onClick={() => navigate(`/${countryRegion.id}`)}>{countryRegion.name}</span></>}
                  {selectedCountry && <><span>›</span><span style={{ cursor:"pointer", color: view!=="country"?"#9a9088":"#1a1714", fontWeight:500 }} onClick={goToCountryBack}>{selectedCountry}</span></>}
                  {selectedDish && <><span>›</span><span style={{ color:"#1a1714", fontWeight:600 }}>{selectedDish}</span></>}
                </>
              )}
            </div>
          )}
        </div>

        {/* Main */}
        <div style={{ position:"relative", backgroundImage:"url(https://images.pexels.com/photos/13832265/pexels-photo-13832265.jpeg?auto=compress&cs=tinysrgb&w=1260&h=750&dpr=1)", backgroundSize:"cover", backgroundPosition:"center", backgroundAttachment:"fixed" }}>
          <div style={{ position:"absolute", inset:0, background:"rgba(253,252,249,0.92)", mixBlendMode:"normal" }} />
          <div style={{ position:"relative", zIndex:1 }}>
        {!["blog","about","contact","privacy","terms"].includes(view) && (
          <div style={{ padding:"32px 24px 60px", maxWidth:960, margin:"0 auto" }}>
            {view === "regions"  && <RegionMap onSelectRegion={goToRegion} />}
            {view === "region"   && selectedRegion && <RegionView regionId={selectedRegion} onBack={goToRegions} onSelectCountry={goToCountry} />}
            {view === "country"  && selectedCountry && <CountryView country={selectedCountry} onBack={goToRegionBack} onSelectDish={goToDish} />}
            {view === "recipe"   && selectedDish && <RecipeView country={recipeCountry || selectedCountry} dish={selectedDish} navigate={navigate} onBack={() => { const r = REGIONS.find(r => r.countries?.includes(recipeCountry)); navigate(recipeCountry && r ? `/${r.id}/${slugify(recipeCountry)}` : '/'); }} />}
            {(view === "region" && !selectedRegion) && <RegionMap onSelectRegion={goToRegion} />}
            {(view === "country" && !selectedCountry) && <RegionMap onSelectRegion={goToRegion} />}
            {(view === "recipe" && !selectedDish) && <RegionMap onSelectRegion={goToRegion} />}
          </div>
        )}

        {/* Info pages */}
        {["blog","about","contact","privacy","terms"].includes(view) && (
          <div style={{ padding:"32px 24px 60px", maxWidth:960, margin:"0 auto" }}>
            <div style={{ maxWidth:680, margin:"0 auto 32px" }}>
              <AdUnit />
            </div>
            {view === "blog" && <BlogPage navigate={navigate} initialSlug={parts[1] || null} />}
            {view === "about" && <AboutPage />}
            {view === "contact" && <ContactPage />}
            {view === "terms" && <TermsPage />}
            {view === "privacy" && <PrivacyPage />}
          </div>
        )}

          </div>
        </div>
        {/* Creative Commons credit strip */}
        <div style={{ padding:"14px 28px", textAlign:"center", borderTop:"1px solid #ece6db" }}>
          <span style={{ fontSize:10, color:"#d8d0c5", fontFamily:"Plus Jakarta Sans" }}>Some recipe photos courtesy of Openverse and Wikimedia Commons contributors, used under Creative Commons licenses.</span>
        </div>
        {/* Footer */}
        <div style={{ borderTop:"1.5px solid #ece6db", padding:"28px", background:"#fdfcf9" }}>
          <div style={{ maxWidth:960, margin:"0 auto" }}>
            <div style={{ display:"flex", flexWrap:"wrap", justifyContent:"space-between", alignItems:"center", gap:16, marginBottom:16 }}>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <circle cx="14" cy="12" r="8" stroke="#c2622a" strokeWidth="1.8" fill="none"/>
                  <path d="M6 12 Q14 8 22 12" stroke="#c2622a" strokeWidth="1.4" fill="none"/>
                  <path d="M6 12 Q14 16 22 12" stroke="#c2622a" strokeWidth="1.4" fill="none"/>
                  <line x1="14" y1="4" x2="14" y2="20" stroke="#c2622a" strokeWidth="1.4"/>
                  <line x1="3" y1="4" x2="3" y2="20" stroke="#c2622a" strokeWidth="2" strokeLinecap="round"/>
                  <line x1="1" y1="4" x2="1" y2="9" stroke="#c2622a" strokeWidth="1.6" strokeLinecap="round"/>
                  <line x1="5" y1="4" x2="5" y2="9" stroke="#c2622a" strokeWidth="1.6" strokeLinecap="round"/>
                  <path d="M1 9 Q3 13 5 9" stroke="#c2622a" strokeWidth="1.6" fill="none"/>
                </svg>
                <div>
                  <div style={{ fontFamily:"Fraunces", fontSize:15, fontWeight:700, color:"#1a1714" }}>Recipe Atlas</div>
                  <div style={{ fontSize:10, color:"#b8b0a8", letterSpacing:".1em", textTransform:"uppercase" }}>World Cuisine Explorer</div>
                </div>
              </div>
              <div style={{ display:"flex", gap:20, flexWrap:"wrap" }}>
                {[["blog","Blog"],["about","About"],["contact","Contact"],["privacy","Privacy"],["terms","Terms"]].map(([v,label]) => (
                  <span key={v} onClick={() => navigate(`/${v}`)}
                    style={{ fontSize:12, color:"#9a9088", cursor:"pointer", fontWeight:500, fontFamily:"Plus Jakarta Sans" }}>
                    {label}
                  </span>
                ))}
              </div>
            </div>
            <div style={{ borderTop:"1px solid #ece6db", paddingTop:16, display:"flex", flexWrap:"wrap", justifyContent:"space-between", gap:8 }}>
              <span style={{ fontSize:11, color:"#c8bfb0", fontFamily:"Plus Jakarta Sans" }}>© {new Date().getFullYear()} Recipe Atlas. All rights reserved.</span>
              <span style={{ fontSize:11, color:"#c8bfb0", fontFamily:"Plus Jakarta Sans" }}>Celebrating food from every corner of the world.</span>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

// ── INFO PAGES ────────────────────────────────────────────────────────
const BLOG_POSTS = [
  {
    slug:"maillard-reaction",
    title:"The Maillard Reaction: Why Searing Meat Matters",
    date:"June 2025", tag:"Science",
    excerpt:"The science behind the browning reaction that creates hundreds of new flavour compounds — and why it's the difference between great and exceptional cooking.",
    body:[
      "If you've ever wondered why a properly seared steak tastes so much better than a pale, grey one — why toast is more delicious than bread, why roasted coffee smells nothing like the raw bean — the answer is the Maillard reaction. It is arguably the most important chemical process in all of cooking, and understanding it will make you a significantly better cook overnight.",
      "The Maillard reaction is named after French chemist Louis-Camille Maillard, who first described it in 1912. It occurs when amino acids and reducing sugars are exposed to heat — typically above 140°C (285°F) — and react to produce hundreds of different flavour and aroma compounds simultaneously. It is not a single reaction but a cascade of hundreds of interconnected ones, which is why browned food is so much more complex and interesting than unbrowned food.",
      "The key insight for cooking is this: the Maillard reaction requires both heat and a relatively dry surface. Water boils at 100°C, which is below the temperature needed for browning. This means a wet or damp surface will spend all its energy evaporating moisture before it can brown. This is why patting meat dry before searing is so important — any moisture on the surface must first evaporate before the Maillard reaction can begin. A wet steak steams rather than sears.",
      "Temperature and time are the two levers you control. Higher heat means faster browning but also a narrower window before burning. Lower heat gives you more control but takes longer. A heavy cast-iron or stainless steel pan holds heat far better than a thin non-stick pan, which is why serious cooks prefer them for searing — when cold meat hits a thin pan, the temperature drops dramatically and the meat steams instead of browning.",
      "The Maillard reaction is also responsible for the crust on bread, the colour and flavour of roasted coffee and chocolate, the aroma of grilled onions, the richness of soy sauce (which undergoes a form of Maillard reaction during fermentation), and the deep complexity of slow-roasted meats. Every time you smell something cooking and think 'that smells incredible', the Maillard reaction is almost certainly responsible.",
      "One practical tip that immediately improves cooking: salt your meat well in advance. Salt draws moisture to the surface initially, but given enough time (at least 45 minutes, ideally overnight), that moisture is reabsorbed along with the dissolved salt. The surface ends up drier and more seasoned than unsalted meat — perfect conditions for the Maillard reaction to do its best work.",
    ]
  },
  {
    slug:"chilli-peppers-guide",
    title:"A Guide to the World's Great Chilli Peppers",
    date:"May 2025", tag:"Ingredients",
    excerpt:"From Mexico's smoky ancho to Thailand's bird's eye and Peru's fruity ají amarillo — a tour of the peppers that define regional cuisines.",
    body:[
      "All chilli peppers belong to the genus Capsicum and originated in the Americas, where they have been cultivated for at least 6,000 years. After Columbus brought them back to Europe in the 15th century, they spread with extraordinary speed along trade routes — reaching India, Africa, Southeast Asia and China within decades. In each new home they were embraced, adapted, and eventually became so central to local cuisine that it is now almost impossible to imagine Korean cooking without gochugaru, Thai cooking without bird's eye chillies, or Indian cooking without the Kashmiri chilli.",
      "The heat in chillies comes from capsaicin, a compound that binds to pain receptors in the mouth and throat, triggering a burning sensation. The Scoville scale measures capsaicin concentration: a bell pepper scores 0, a jalapeño around 5,000, a bird's eye chilli around 100,000, and the Carolina Reaper (currently the world's hottest) over 2 million. But heat is only one dimension. Flavour, fruitiness, smokiness and earthiness vary enormously between varieties, which is why great chilli cooks use different peppers for different purposes.",
      "Mexico has the most diverse and sophisticated chilli culture in the world. The ancho (a dried poblano) is earthy and mildly hot, essential for mole. The mulato is darker and more chocolatey. The guajillo is bright red with a berry-like quality, used in pozole and enchilada sauces. The chipotle is a smoked jalapeño — smoky, hot and deeply complex. The pasilla is long and dark with a raisiny, almost liquorice character. Great Mexican cooking often blends two or three dried chillies to build a sauce of genuine complexity.",
      "In Peru, the ají amarillo is the foundation of the national cuisine — a bright orange chilli with a distinctly fruity, almost tropical flavour and a medium heat. It appears in ceviche, causa rellena, ají de gallina and dozens of other dishes. The ají panca is darker and earthier, used in anticuchos and stews. The rocoto is small and red with a fierce heat hidden beneath an almost bell-pepper sweetness.",
      "Thailand's bird's eye chilli (prik kee noo) is tiny, fierce and aromatic — used fresh in curries, soups and salads. The longer prik chee fah is milder and used more for colour. In Korea, gochugaru (dried red pepper flakes) and gochujang (fermented red pepper paste) are the defining flavour of the cuisine — medium hot with a distinct sweetness from the fermentation. In India, the Kashmiri chilli provides vivid red colour with mild heat, while the guntur sannam of Andhra Pradesh is intensely hot.",
      "The practical lesson: don't think of chillies as simply a heat dial. Think of them as flavour ingredients with heat as a secondary consideration. A dish made with anchos tastes fundamentally different from the same dish made with chipotles, even at the same heat level. Learning to distinguish and cook with different chilli varieties is one of the most rewarding steps any cook can take.",
    ]
  },
  {
    slug:"fermentation-guide",
    title:"Why Fermentation is the Secret Ingredient in Every Culture",
    date:"May 2025", tag:"Technique",
    excerpt:"Kimchi, miso, injera — across every continent, fermentation transforms simple ingredients into some of the world's most complex flavours.",
    body:[
      "Before refrigeration, before canning, before any of the modern methods of food preservation, almost every culture on Earth independently discovered fermentation. And in doing so, they accidentally created some of the most complex, flavourful and nutritious foods in human history. Fermentation is not a technique — it is a transformation. Ordinary cabbage becomes kimchi. Soybeans become miso or soy sauce. Milk becomes cheese or yoghurt. Grapes become wine. Barley becomes beer. Wheat flour and water become sourdough. In each case, microorganisms — bacteria, yeasts, moulds — consume the original ingredients and produce something entirely new.",
      "The Korean kimchi tradition is perhaps the world's most sophisticated fermentation culture. Baechu-kimchi, made from napa cabbage, gochugaru, garlic, ginger and salted shrimp, undergoes a lactic acid fermentation driven by Lactobacillus bacteria naturally present on the vegetables. As fermentation proceeds over days, weeks or months, the kimchi becomes progressively more sour, complex and funky. Freshly made kimchi is bright and crunchy; six-month-old kimchi is deeply sour, almost fizzy, and transforms into a completely different ingredient used for kimchi jjigae and kimchi pancakes.",
      "Japan's fermentation tradition is equally remarkable. Miso is made by fermenting soybeans with salt and a mould called koji (Aspergillus oryzae) — a process that can take anywhere from weeks to years. White miso ferments briefly and tastes mild and sweet. Red miso ferments for up to three years and develops a deep, almost meaty intensity. Soy sauce uses the same koji mould applied to a mixture of soybeans and wheat, fermented for months. The result is one of the most umami-rich substances known to cooking.",
      "In Ethiopia, injera is made from teff flour fermented with wild yeasts for two to three days. The fermentation produces lactic acid, giving the flatbread its characteristic sourness, and carbon dioxide, which creates the distinctive porous, spongy texture. The fermentation also makes the teff's nutrients more bioavailable — an important consideration in a diet where injera is eaten at almost every meal. In West Africa, locust beans are fermented to produce iru or dawadawa — a pungent, deeply flavoured seasoning used as a flavour base similar to the role of fish sauce in Southeast Asia.",
      "The science of why fermentation improves flavour is now well understood. Microorganisms produce enzymes that break down proteins into amino acids (including glutamate, the source of umami), starches into sugars, and fats into fatty acids. They produce organic acids that add sourness and brightness. They produce esters and other aromatic compounds that add fruity, floral and earthy notes. The result is food that is more complex, more digestible and often more nutritious than the raw ingredients.",
      "For home cooks, the practical message is simple: fermented ingredients are flavour shortcuts. A spoonful of miso adds weeks of fermentation complexity to a dish. A good aged parmesan — itself a fermented product — adds a deep savouriness that young cheese cannot match. A properly fermented hot sauce has a rounded, complex heat that fresh chillies alone cannot produce. Learning to use fermented condiments — miso, fish sauce, soy sauce, gochujang, preserved lemons, good vinegars — is one of the fastest ways to add depth to everyday cooking.",
    ]
  },
  {
    slug:"spice-routes-history",
    title:"The Spice Routes That Changed World Food Forever",
    date:"April 2025", tag:"History",
    excerpt:"How the medieval spice trade didn't just make merchants rich — it fundamentally altered what every culture in the world ate and still eats today.",
    body:[
      "It is difficult to overstate how valuable spices were in medieval Europe. Pepper, cloves, nutmeg, cinnamon and cardamom were worth their weight in silver and sometimes gold. Pepper was used as currency and to pay ransoms. When the Visigoths sacked Rome in 410 CE, their ransom demand included 3,000 pounds of pepper. The entire infrastructure of medieval European commerce — the merchant republics of Venice and Genoa, the rise of banking, the first joint-stock companies — was built substantially on the spice trade.",
      "The reason European spices were so expensive was geography. They grew in the islands of Southeast Asia, in India and in Sri Lanka. To reach Europe, they travelled overland through Central Asia and the Middle East or by sea through the Indian Ocean and the Persian Gulf, passing through dozens of middlemen — Arab, Persian, Indian and Ottoman merchants — each taking a margin. By the time pepper reached Lisbon or Venice, its price had increased a hundredfold from its origin.",
      "This extraordinary price differential is what drove the Age of Exploration. Portugal's Vasco da Gama rounded the Cape of Good Hope in 1498 not out of curiosity but out of commercial calculation — if spices could be obtained directly from their source, the profits would be enormous. Columbus sailed west in 1492 with the same commercial logic, believing he could reach the spice islands of Asia. He found the Americas instead — and with them, an entirely different category of ingredients that would transform world cuisine.",
      "The Columbian Exchange — the transfer of plants, animals and diseases between the Americas and the rest of the world after 1492 — is the single most transformative event in culinary history. From the Americas came tomatoes, potatoes, maize, chillies, chocolate, vanilla, peanuts, squash, beans, and turkey. Within 200 years of Columbus, these ingredients had been adopted and adapted into cuisines across Europe, Africa and Asia. Today it is impossible to imagine Italian cooking without tomatoes, Indian cooking without chillies, Irish cooking without potatoes, or Thai cooking without chillies and peanuts — yet all of these ingredients arrived in those cuisines only after 1500.",
      "The spice trade also drove the development of the world's most complex spice-blending traditions. Indian masalas, Moroccan ras el hanout, Ethiopian berbere, the baharat of the Arab world — these sophisticated spice blends developed in cultures that sat along the trading routes and had access to the widest variety of spices. The more spices available, the more complex the blending tradition that developed around them.",
      "The legacy of the spice trade is written into every cuisine on earth. The chilli in your Korean kimchi, the vanilla in your French crème brûlée, the black pepper in your Italian pasta — all are products of trade routes that began over 2,000 years ago. Modern globalisation of food is not a new phenomenon. It is the continuation of a process that has been reshaping what humanity eats since the first merchant loaded cinnamon onto a ship.",
    ]
  },
  {
    slug:"umami-fifth-taste",
    title:"Umami: The Fifth Taste and How to Cook With It",
    date:"April 2025", tag:"Science",
    excerpt:"Discovered in Japan in 1908, umami is the savoury depth in parmesan, anchovies, soy sauce and tomatoes — the secret behind the world's most satisfying dishes.",
    body:[
      "For most of Western culinary history, taste was understood as four things: sweet, sour, salty and bitter. Then in 1908, a Japanese chemist named Kikunae Ikeda was eating a bowl of dashi — the clear Japanese stock made from kombu seaweed and dried bonito flakes — and noticed something. The stock had a distinct savouriness that couldn't be explained by saltiness alone. It was rich, mouth-coating and persistent. He isolated the compound responsible: glutamate, specifically L-glutamate, a naturally occurring amino acid. He named the taste it produced umami — from the Japanese umai (delicious) and mi (taste).",
      "Ikeda went on to develop monosodium glutamate (MSG) as a flavour enhancer, which became one of the most used and most misunderstood food additives in history. The association of MSG with the so-called 'Chinese restaurant syndrome' has been thoroughly debunked — multiple double-blind studies have found no evidence that MSG causes any symptoms in the vast majority of people, and the FDA classifies it as generally safe. Meanwhile, glutamate occurs naturally at high concentrations in parmesan cheese, ripe tomatoes, anchovies, soy sauce, mushrooms, marmite and cured meats — foods that have been central to great cooking for centuries.",
      "Umami works differently from the other four tastes. While sweetness and saltiness are relatively simple sensory experiences, umami is more complex — it enhances and rounds other flavours, adds a sense of depth and persistence, and creates what Japanese cooks call kokumi (richness or body). A dish with well-developed umami doesn't just taste savoury — it tastes more of itself. The other flavours are amplified and integrated rather than competing separately.",
      "The practical cooking implications are significant. Umami compounds are particularly concentrated in aged, fermented, dried and slow-cooked foods. Parmesan aged for 24 months has far more glutamate than young cheese. Anchovies that have been salt-cured for a year are umami bombs. A tomato paste cooked down until it darkens has more umami than fresh tomatoes. Fish sauce, made from fermented anchovies, is perhaps the most concentrated source of umami in any cuisine.",
      "Synergy is the most powerful umami concept for cooks: certain combinations of umami compounds produce dramatically more savouriness together than the sum of their parts. Glutamate (in tomatoes, parmesan, mushrooms) combined with inosinate (in meat and fish) produces a synergistic effect that multiplies the perceived umami five to eight times. This is why bolognese tastes richer than minced beef alone, why parmesan on pasta is transformative, and why the Japanese combination of kombu (glutamate) and bonito (inosinate) in dashi produces such an extraordinarily savoury stock from just two ingredients.",
      "To cook with more umami: fry your tomato paste in oil before adding liquid — this concentrates and deepens its glutamate content. Add a parmesan rind to soups and stews. Use a small amount of fish sauce or soy sauce in non-Asian dishes as a background note rather than a primary flavour. Cook dried mushrooms into stocks or sauces. Reduce and caramelise onions — both processes increase glutamate. None of these additions need to be identifiable in the finished dish. They work in the background, adding the depth and persistence that makes food taste more satisfying.",
    ]
  },
  {
    slug:"street-food-guide",
    title:"Street Food: Why the Best Meals Are Often the Cheapest",
    date:"March 2025", tag:"Culture",
    excerpt:"From Bangkok's night markets to Lagos's suya stalls and Mexico City's taquerias — why street food produces the world's most honest, flavourful cooking.",
    body:[
      "There is a persistent and largely false idea that the best food is expensive food. That quality correlates with price, that a dish served on fine china in a hushed dining room with three sommeliers necessarily represents better cooking than the same meal eaten standing up at a stall in a night market. Travel widely and eat hungrily and this idea dissolves quickly. Some of the most extraordinary food on earth is made by people who have cooked one or two dishes every day for twenty years from a cart on a street corner.",
      "The street food vendor's advantage is focus. A great restaurant kitchen might have dozens of dishes on the menu, requiring a brigade of cooks to execute across multiple stations. A street food vendor makes one thing — tacos al pastor, pad thai, suya, pho, jerk chicken — and makes it every day, all day, for years. This repetition produces a level of consistency and refinement that is almost impossible to achieve otherwise. The taco al pastor vendor who has been slicing meat from the same trompo for fifteen years is not making tacos — he is performing a craft that has been refined to near perfection.",
      "Street food also benefits from the economics of constraint. When your margins are razor thin, waste is existential. This produces an obsession with using every part of every ingredient — offal dishes, bone broths, vegetable scraps — that drives genuine creativity. Many of the world's most celebrated dishes began as poverty food: pho was originally made from the bones and offcuts that the French colonial authorities didn't want. Coxinha was invented to use chicken necks and backs. Tacos al pastor were created by Lebanese immigrants adapting the shawarma tradition to Mexican ingredients, using the cheaper shoulder cut.",
      "The great street food cities — Bangkok, Mexico City, Hanoi, Istanbul, Lagos, Singapore, Mumbai, Lima — tend to be cities with strong culinary traditions, intense competition among vendors, and populations with sophisticated palates who eat street food as a genuine choice rather than a compromise. In Bangkok, office workers earning good salaries choose the 40-baht pad thai at the corner stall over air-conditioned restaurants not because they can't afford the restaurant but because the pad thai is better. Competition is fierce and unforgiving — vendors who don't maintain quality lose customers to the stall next door within days.",
      "The theatre of street food is also part of its appeal. The wok tossed over a roaring flame, the meat sliced in long thin strips from a rotating spit, the dough stretched transparent-thin on an oiled surface, the soup ladled from an enormous pot that has been simmering since 4am — these are not performances for tourists but the visible evidence of technique, the spectacle of skill deployed at high speed in a tiny space. Watching a great street food cook work is as compelling as watching any other artisan.",
      "If there is a philosophy embedded in great street food it is this: respect your ingredients, perfect your technique, and don't add anything that doesn't belong. The best tacos contain three things: good tortillas, properly cooked meat, and the right salsa. The best pho is a clear broth of extraordinary depth with fresh noodles and simple garnishes. Complexity comes from technique and time, not from ingredient lists. This is perhaps the most important lesson any cook can learn — and it costs nothing more than a trip to a street market and an open mind.",
    ]
  },
];

function BlogPage({ initialSlug, navigate }) {
  const slugToIndex = slug => BLOG_POSTS.findIndex(p => p.slug === slug);
  const [activePost, setActivePost] = useState(() => initialSlug ? slugToIndex(initialSlug) : null);

  useEffect(() => {
    if (activePost !== null && activePost >= 0) {
      const post = BLOG_POSTS[activePost];
      document.title = `${post.title} | Recipe Atlas`;
      const metaDesc = document.querySelector('meta[name="description"]');
      if (metaDesc) metaDesc.content = `${post.excerpt.replace(/\.+$/, '')}.`;
    }
  }, [activePost]);

  useEffect(() => { window.scrollTo(0, 0); }, [activePost]);

  const openPost = (i) => {
    setActivePost(i);
    if (navigate) navigate(`/blog/${BLOG_POSTS[i].slug}`);
  };
  const closePost = () => {
    setActivePost(null);
    if (navigate) navigate('/blog');
  };

  if (activePost !== null && activePost >= 0) {
    const post = BLOG_POSTS[activePost];
    return (
      <div style={{ maxWidth:680, margin:"0 auto" }}>
        <button onClick={closePost}
          style={{ background:"none", border:"none", color:"#c2622a", cursor:"pointer", fontSize:13, fontWeight:600, fontFamily:"Plus Jakarta Sans", marginBottom:20, padding:0, display:"flex", alignItems:"center", gap:6 }}>
          ← Back to Blog
        </button>
        <div style={{ display:"flex", gap:8, marginBottom:12, flexWrap:"wrap" }}>
          <span style={{ fontSize:11, background:"#fdf3ed", color:"#c2622a", padding:"3px 10px", borderRadius:20, fontWeight:600, fontFamily:"Plus Jakarta Sans" }}>{post.tag}</span>
              </div>
        <h1 style={{ fontFamily:"Fraunces", fontSize:"clamp(22px,3vw,36px)", fontWeight:700, color:"#1a1714", marginBottom:20, lineHeight:1.25 }}>{ post.title}</h1>
        <div style={{ marginTop:24 }}>
          {post.body.map((para, i) => (
            <p key={i} style={{ fontSize:15, color:"#3a3028", lineHeight:1.9, marginBottom:20 }}>{para}</p>
          ))}
        </div>
        <AdUnit style={{ marginTop:24 }} />
      </div>
    );
  }

  return (
    <div>
      <h1 style={{ fontFamily:"Fraunces", fontSize:"clamp(24px,3vw,40px)", fontWeight:700, color:"#1a1714", marginBottom:8 }}>The Recipe Atlas Blog</h1>
      <p style={{ fontSize:15, color:"#9a9088", lineHeight:1.7, marginBottom:24 }}>Stories, techniques and histories from the world's great food cultures.</p>
      <div style={{ display:"grid", gap:20, marginTop:24 }}>
        {BLOG_POSTS.map((p,i) => (
          <div key={i} onClick={() => openPost(i)}
            style={{ background:"#fff", border:"1.5px solid #ece6db", borderRadius:12, padding:24, cursor:"pointer", transition:"border-color .2s, box-shadow .2s" }}
            onMouseEnter={e => { e.currentTarget.style.borderColor="#c2622a"; e.currentTarget.style.boxShadow="0 2px 12px rgba(194,98,42,.08)"; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor="#ece6db"; e.currentTarget.style.boxShadow="none"; }}>
            <div style={{ display:"flex", gap:8, marginBottom:10, flexWrap:"wrap" }}>
              <span style={{ fontSize:11, background:"#fdf3ed", color:"#c2622a", padding:"3px 10px", borderRadius:20, fontWeight:600, fontFamily:"Plus Jakarta Sans" }}>{p.tag}</span>
            </div>
            <h2 style={{ fontFamily:"Fraunces", fontSize:18, fontWeight:700, color:"#1a1714", marginBottom:8, lineHeight:1.3 }}>{p.title}</h2>
            <p style={{ fontSize:14, color:"#6a6058", lineHeight:1.75, margin:"0 0 12px" }}>{p.excerpt}</p>
            <span style={{ fontSize:12, color:"#c2622a", fontWeight:600, fontFamily:"Plus Jakarta Sans" }}>Read article →</span>
          </div>
        ))}
      </div>
      <div style={{ maxWidth:680, margin:"24px auto 0" }}>
        <AdUnit />
      </div>
    </div>
  );
}

